html:div.html:script:
(() => {
  const form = document.getElementById("site-form");
  const input = document.getElementById("site-url");
  const frame = document.getElementById("site-frame");
  const openLink = document.getElementById("open-site");
  const message = document.getElementById("message");

  form.addEventListener("submit", (event) => {
    event.preventDefault();
    if (!input.reportValidity()) return;

    let target;
    try {
      target = new URL(input.value.trim());
    } catch {
      message.textContent = "Enter a valid deployed Lyra URL.";
      return;
    }
    if (target.protocol !== "https:" && target.protocol !== "http:") {
      message.textContent = "Only HTTP or HTTPS site URLs can be loaded.";
      return;
    }

    target.hash = "";
    input.value = target.href;
    frame.src = target.href;
    openLink.href = target.href;
    openLink.setAttribute("aria-disabled", "false");
    message.textContent = "Loading the deployed site. Embedding may be blocked by that site's frame policy; use Open in new tab if needed.";
  });

  frame.addEventListener("load", () => {
    if (frame.src !== "about:blank") {
      message.textContent = "The page loaded in the frame. Cross-origin browser rules prevent this wrapper from confirming app readiness.";
    }
  });

  document.getElementById("fullscreen").addEventListener("click", async () => {
    try {
      if (!document.fullscreenElement) await document.documentElement.requestFullscreen();
      else await document.exitFullscreen();
    } catch {
      message.textContent = "Fullscreen is unavailable in this browser or viewing context.";
    }
  });

  openLink.addEventListener("click", (event) => {
    if (openLink.getAttribute("aria-disabled") === "true") event.preventDefault();
  });
})();
